import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { test } from 'node:test'
import { isBinaryPlist, looksLikeXmlPlist, parsePlist } from './plistParser.js'

/** ArrayBuffer of a fixture generated by __fixtures__/make_safari_fixtures.py. */
function fixture(name) {
  const bytes = readFileSync(new URL(`./__fixtures__/${name}`, import.meta.url))
  return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength)
}

test('recognizes binary and XML property lists', () => {
  assert.equal(isBinaryPlist(fixture('plist-types.bplist')), true)
  assert.equal(isBinaryPlist(new TextEncoder().encode('SQLite format 3\0').buffer), false)
  assert.equal(looksLikeXmlPlist('<?xml version="1.0"?>\n<!DOCTYPE plist><plist version="1.0">'), true)
  assert.equal(looksLikeXmlPlist('﻿<plist version="1.0"><dict/></plist>'), true)
  assert.equal(looksLikeXmlPlist('<?xml version="1.0"?><html/>'), false)
  assert.equal(looksLikeXmlPlist('{"json": true}'), false)
})

test('decodes every binary plist object type', () => {
  const value = parsePlist(fixture('plist-types.bplist'))
  assert.equal(value.ascii, 'plain')
  assert.equal(value.long, 'a string longer than fourteen characters')
  assert.equal(value.unicode, 'Caffè ☕ Привет')
  assert.equal(value.zero, 0)
  assert.equal(value.small, 200)
  assert.equal(value.medium, 70000)
  assert.equal(value.negative, -42)
  assert.equal(value.big, 2 ** 40)
  assert.equal(value.huge, 2n ** 62n)
  assert.equal(value.real, 3.5)
  assert.equal(value.yes, true)
  assert.equal(value.no, false)
  assert.equal(value.when.toISOString(), '2026-11-04T10:30:00.000Z')
  assert.deepEqual([...value.blob], [0x00, 0x01, 0xfe, 0xff])
  assert.deepEqual(value.uid, { UID: 7 })
  assert.deepEqual(value.nested, { list: [1, 'two', { three: 3 }] })
  assert.deepEqual(
    value.many,
    Array.from({ length: 300 }, (_, i) => i),
  )
})

test('rejects truncated or non-plist input with a clear error', () => {
  const bytes = new Uint8Array(fixture('safari-downloads.bplist'))
  const truncated = bytes.slice(0, bytes.length - 40).buffer
  assert.throws(() => parsePlist(truncated), /Corrupted binary plist|Not a property list/)
  assert.throws(() => parsePlist(new TextEncoder().encode('hello').buffer), /Not a property list/)
})

test('rejects a trailer pointing outside the file', () => {
  const bytes = new Uint8Array(fixture('safari-downloads.bplist'))
  const view = new DataView(bytes.buffer)
  view.setBigUint64(bytes.length - 8, 0xffffffn) // offset table beyond the end
  assert.throws(() => parsePlist(bytes.buffer), /Corrupted binary plist/)
})
